CREATE TABLE `users` (`id` VARCHAR(30) NOT NULL,`email` VARCHAR(320) NOT NULL,`password_hash` VARCHAR(255) NULL,`name` VARCHAR(160) NULL,`image` VARCHAR(2048) NULL,`status` VARCHAR(20) NOT NULL DEFAULT 'active',`must_change_password` BOOLEAN NOT NULL DEFAULT false,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `users_email_key` (`email`));
CREATE TABLE `profiles` (`user_id` VARCHAR(30) NOT NULL,`display_name` VARCHAR(160) NULL,`avatar_url` VARCHAR(2048) NULL,`preferred_lang` VARCHAR(8) NOT NULL DEFAULT 'en',`theme` VARCHAR(12) NOT NULL DEFAULT 'light',PRIMARY KEY (`user_id`),CONSTRAINT `profiles_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `sessions` (`id` VARCHAR(64) NOT NULL,`user_id` VARCHAR(30) NOT NULL,`expires_at` DATETIME(3) NOT NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`user_agent` VARCHAR(512) NULL,PRIMARY KEY (`id`),INDEX `sessions_user_id_expires_at_idx` (`user_id`,`expires_at`),CONSTRAINT `sessions_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `accounts` (`id` VARCHAR(30) NOT NULL,`user_id` VARCHAR(30) NOT NULL,`provider` VARCHAR(40) NOT NULL,`provider_account_id` VARCHAR(255) NOT NULL,PRIMARY KEY (`id`),UNIQUE INDEX `accounts_provider_provider_account_id_key` (`provider`,`provider_account_id`),INDEX `accounts_user_id_idx` (`user_id`),CONSTRAINT `accounts_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `password_reset_tokens` (`id` VARCHAR(64) NOT NULL,`user_id` VARCHAR(30) NOT NULL,`expires_at` DATETIME(3) NOT NULL,`used_at` DATETIME(3) NULL,PRIMARY KEY (`id`),INDEX `password_reset_tokens_user_id_expires_at_idx` (`user_id`,`expires_at`),CONSTRAINT `password_reset_tokens_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `conversations` (`id` VARCHAR(30) NOT NULL,`user_id` VARCHAR(30) NOT NULL,`title` VARCHAR(255) NOT NULL DEFAULT 'New Chat',`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),INDEX `conversations_user_id_updated_at_idx` (`user_id`,`updated_at`),CONSTRAINT `conversations_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `messages` (`id` BIGINT NOT NULL AUTO_INCREMENT,`conversation_id` VARCHAR(30) NOT NULL,`role` VARCHAR(16) NOT NULL,`request_id` VARCHAR(36) NULL,`content` LONGTEXT NOT NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),UNIQUE INDEX `messages_conversation_id_request_id_key` (`conversation_id`,`request_id`),INDEX `messages_conversation_id_created_at_idx` (`conversation_id`,`created_at`),CONSTRAINT `messages_conversation_id_fkey` FOREIGN KEY (`conversation_id`) REFERENCES `conversations` (`id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `admin_users` (`user_id` VARCHAR(30) NOT NULL,`role` VARCHAR(20) NOT NULL DEFAULT 'admin',`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`user_id`),CONSTRAINT `admin_users_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `provider_logs` (`id` BIGINT NOT NULL AUTO_INCREMENT,`provider` VARCHAR(32) NOT NULL,`key_index` INTEGER NULL,`user_id` VARCHAR(30) NULL,`success` BOOLEAN NOT NULL,`response_time_ms` INTEGER NULL,`status_code` INTEGER NULL,`error_code` VARCHAR(64) NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),INDEX `provider_logs_provider_created_at_idx` (`provider`,`created_at`));
CREATE TABLE `provider_key_stats` (`id` VARCHAR(80) NOT NULL,`provider` VARCHAR(32) NOT NULL,`key_index` INTEGER NOT NULL,`status` VARCHAR(20) NOT NULL DEFAULT 'healthy',`success_count` INTEGER NOT NULL DEFAULT 0,`failure_count` INTEGER NOT NULL DEFAULT 0,`cooldown_until` DATETIME(3) NULL,`last_used` DATETIME(3) NULL,`last_success` DATETIME(3) NULL,`last_failure` DATETIME(3) NULL,PRIMARY KEY (`id`),UNIQUE INDEX `provider_key_stats_provider_key_index_key` (`provider`,`key_index`));
CREATE TABLE `app_settings` (`key` VARCHAR(100) NOT NULL,`value` JSON NOT NULL,`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`key`));
CREATE TABLE `plans` (`id` VARCHAR(20) NOT NULL,`name` VARCHAR(80) NOT NULL,`price` DECIMAL(12,2) NOT NULL DEFAULT 0,`currency` VARCHAR(8) NOT NULL DEFAULT 'BDT',`message_limit` INTEGER NOT NULL,`pdf_limit` INTEGER NOT NULL,`image_limit` INTEGER NOT NULL,`active` BOOLEAN NOT NULL DEFAULT true,`display_order` INTEGER NOT NULL DEFAULT 0,`description` TEXT NULL,`features` JSON NULL,PRIMARY KEY (`id`));
CREATE TABLE `subscription_requests` (`id` VARCHAR(30) NOT NULL,`user_id` VARCHAR(30) NOT NULL,`plan_id` VARCHAR(20) NOT NULL,`status` VARCHAR(20) NOT NULL DEFAULT 'pending',`price_at_request` DECIMAL(12,2) NOT NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),`updated_at` DATETIME(3) NOT NULL,PRIMARY KEY (`id`),INDEX `subscription_requests_user_id_created_at_idx` (`user_id`,`created_at`),CONSTRAINT `subscription_requests_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,CONSTRAINT `subscription_requests_plan_id_fkey` FOREIGN KEY (`plan_id`) REFERENCES `plans` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE);
CREATE TABLE `usage_counters` (`id` VARCHAR(30) NOT NULL,`user_id` VARCHAR(30) NOT NULL,`period` VARCHAR(10) NOT NULL,`date` DATE NOT NULL,`messages` INTEGER NOT NULL DEFAULT 0,`pdfs` INTEGER NOT NULL DEFAULT 0,`images` INTEGER NOT NULL DEFAULT 0,PRIMARY KEY (`id`),UNIQUE INDEX `usage_counters_user_id_period_date_key` (`user_id`,`period`,`date`),CONSTRAINT `usage_counters_user_id_fkey` FOREIGN KEY (`user_id`) REFERENCES `users` (`id`) ON DELETE CASCADE ON UPDATE CASCADE);
CREATE TABLE `audit_logs` (`id` BIGINT NOT NULL AUTO_INCREMENT,`actor_id` VARCHAR(30) NULL,`action` VARCHAR(100) NOT NULL,`target` VARCHAR(160) NULL,`metadata` JSON NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),INDEX `audit_logs_actor_id_created_at_idx` (`actor_id`,`created_at`));
CREATE TABLE `user_activity_logs` (`id` BIGINT NOT NULL AUTO_INCREMENT,`user_id` VARCHAR(30) NULL,`action` VARCHAR(80) NOT NULL,`metadata` JSON NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`),INDEX `user_activity_logs_user_id_created_at_idx` (`user_id`,`created_at`));
CREATE TABLE `feedback` (`id` VARCHAR(30) NOT NULL,`user_id` VARCHAR(30) NULL,`message` TEXT NOT NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`id`));
